export const scoreAll = (leads, weights, trigger, by = 'system') => leads.map((l) => { const r = scoreLead(l, { weights }); return { ...l, scoreInfo: r, history: appendHistory(l.history, historyEntry(r, trigger, new Date().toISOString(), by)) } })
export function seedState() { return scoreAll(SEED_LEADS, DEFAULT_WEIGHTS, 'Initial score') }


export const newLead = (o) => L({ id: `l${Date.now()}`, relationshipSince: null, source: 'Manual', lastContact: 'Today', ...o })
